---@alias gcp.androidenterprise_v1.ProductVisibilityList gcp.androidenterprise_v1.ProductVisibility[]

---@alias gcp.androidenterprise_v1.ProductVisibilityTracksItemEnum "appTrackUnspecified"|"production"|"beta"|"alpha"

